14	const PAGE_LIMIT = 50
15	
16	export default function App() {
17	  const [items, setItems] = useState<WorkItem[]>([])
18	  const [selected, setSelected] = useState<WorkItem | null>(null)
19	  const [filter, setFilter] = useState<WorkStatus | 'all'>('all')
20	  const [source, setSource] = useState<SourceKind | 'all'>('all')
21	  const [query, setQuery] = useState('')
22	  const [state, setState] = useState<'checking' | 'ready' | 'offline'>('checking')
23	  const [demo, setDemo] = useState(false)
24	  const [settings, setSettings] = useState(false)
25	  const [palette, setPalette] = useState(false)
26	  const [toast, setToast] = useState('')
27	  const [locked, setLocked] = useState(false)
28	  const [remoteTotal, setRemoteTotal] = useState(0)
29	  const [loadedCount, setLoadedCount] = useState(0)
30	  const [loadingMore, setLoadingMore] = useState(false)
31	  const [missed, setMissed] = useState<Source[]>([])
32	
33	  const loadMissed = async (loadedItems: WorkItem[]) => {
34	    try {
35	      const page = await getSources({ limit: 200 })
36	      const promoted = new Set(loadedItems.map(i => i.source_external_id).filter((id): id is string => Boolean(id)))
37	      setMissed((page.items ?? []).filter(candidate => !promoted.has(candidate.external_id)))
38	    } catch { setMissed([]) }
39	  }
40	
41	  const loadWork = async () => {
42	    try {
43	      await getHealth()
44	      await restoreLocalSession()
45	      const page = await getWorkItems()
46	      const work = page.items.filter(i => i.status !== 'dismissed')
47	      setState('ready'); setLocked(false); setDemo(false)
48	      setItems(work); setSelected(work[0] ?? null)
49	      setRemoteTotal(page.total); setLoadedCount(page.items.length)
50	      void loadMissed(work)
51	    } catch (error) {
52	      if (error instanceof ApiError && (error.status === 401 || error.status === 503)) { setState('offline'); setLocked(true); return }
53	      setState('offline'); setDemo(true); setItems(demoItems); setSelected(demoItems[0])
54	      setRemoteTotal(demoItems.length); setLoadedCount(demoItems.length); setMissed([])
55	    }
56	  }
57	
58	  const loadMore = async () => {
59	    setLoadingMore(true)
60	    try {
61	      const page = await getWorkItems({ limit: PAGE_LIMIT, offset: loadedCount })
62	      const additions = page.items.filter(i => i.status !== 'dismissed')
63	      setItems(all => [...all, ...additions]); setRemoteTotal(page.total); setLoadedCount(count => count + page.items.length)
64	    } catch { setToast('Could not load more items.') }
65	    finally { setLoadingMore(false) }
66	  }
67	
68	  useEffect(() => { void loadWork() }, [])
69	
70	  useEffect(() => {
71	    const onKeyDown = (event: KeyboardEvent) => {
72	      if (event.key.toLowerCase() === 'k' && (event.metaKey || event.ctrlKey)) { event.preventDefault(); setPalette(open => !open) }
73	    }
74	    window.addEventListener('keydown', onKeyDown)
75	    return () => window.removeEventListener('keydown', onKeyDown)
76	  }, [])
77	
78	  const unlock = async (token: string) => {
79	    try { await startLocalSession(token); await loadWork() } catch { setToast('That local token could not unlock Magic Tower.') }
80	  }
81	  const connectMicrosoft = async () => {
82	    try { await beginMicrosoftConnect() } catch { setToast('Microsoft connection could not start.') }
83	  }
84	  const runSync = async () => {
85	    try { const result = await syncNow(); await loadWork(); setToast(result.detail || 'Microsoft messages synced.') } catch { setToast('Sync could not be completed.') }
86	  }
87	  const handoff = async (item: WorkItem, client: 'codex' | 'claude-code') => {
88	    try { await createDispatch(item.id, client, 'Review the local Magic Tower item and propose the next safe action.'); setToast(`Queued a ${client} handoff.`) } catch { setToast('Could not queue the agent handoff.') }
89	  }
90	  const showDemo = () => {
91	    setDemo(true); setItems(demoItems); setSelected(demoItems[0]); setToast('Showing sample items — connect the API for your work queue.')
92	  }
93	  const choose = async (item: WorkItem) => {
94	    setSelected(item)
95	    if (!demo) try { setSelected(await getWorkItem(item.id)) } catch { /* list summary remains usable */ }
96	  }
97	  const changeStatus = async (status: WorkStatus) => {
98	    if (!selected) return
99	    const old = selected
100	    const next = { ...old, status }
101	    setSelected(next); setItems(all => all.map(i => i.id === next.id ? next : i))
102	    if (!demo) try {
103	      const saved = await updateWorkItem(old.id, { status })
104	      setSelected(saved); setItems(all => all.map(i => i.id === saved.id ? saved : i))
105	    } catch {
106	      setSelected(old); setItems(all => all.map(i => i.id === old.id ? old : i)); setToast('Could not save that change.')
107	    }
108	  }
109	  const dismiss = async (item: WorkItem) => {
110	    // Dismissing moves a row to the 'dismissed' status rather than deleting it, so the server's
111	    // unfiltered total is unchanged — decrementing it here would strand the still-unfetched pages.
112	    setItems(all => all.filter(i => i.id !== item.id))
113	    setSelected(current => current?.id === item.id ? null : current)
114	    if (demo) { setToast('Dismissed the sample item.'); return }
115	    try { await dismissWorkItem(item.id); setToast('Dismissed. It will stay out of the queue.') }
116	    catch {
117	      setItems(all => [item, ...all]); setSelected(item)
118	      setToast('Could not dismiss that item.')
119	    }
120	  }
121	  const promote = async (candidate: Source) => {
122	    try {
123	      const created = await promoteSource(candidate.id)
124	      setMissed(all => all.filter(s => s.id !== candidate.id))
125	      setItems(all => [created, ...all]); setSelected(created); setRemoteTotal(t => t + 1)
126	      setToast('Promoted to your work queue.')
127	    } catch { setToast('Could not promote that source.') }
128	  }
129	
130	  const visible = useMemo(
131	    () => items.filter(i => (filter === 'all' || i.status === filter) && (source === 'all' || i.source_kind === source) && `${i.title} ${i.summary ?? ''}`.toLowerCase().includes(query.toLowerCase())),
132	    [items, filter, source, query],
133	  )
134	
135	  return (
136	    <div className="flex h-screen flex-col">
137	      <header className="flex items-center justify-between gap-3 border-b border-border px-4 py-2.5">
138	        <div className="flex items-center gap-3">
139	          <img src="/magic-tower-logo.png" alt="Magic Tower" className="size-8 object-contain" />
140	          <div>
141	            <h1 className="font-serif text-base leading-tight">Magic Tower</h1>
142	            <p className="text-[0.68rem] text-muted-foreground">A private task grimoire</p>
143	          </div>
144	        </div>
145	        <div className="flex items-center gap-2">
146	          <Button variant="outline" size="sm" onClick={() => setPalette(true)}>
147	            <SearchIcon />Search
148	            <kbd className="ml-2 rounded-sm bg-secondary px-1.5 py-0.5 text-[0.65rem] text-muted-foreground">⌘K</kbd>
149	          </Button>
150	          <span className={state === 'ready' ? 'text-xs text-emerald-300' : 'text-xs text-muted-foreground'}>
151	            {state === 'ready' ? '● Synced locally' : state === 'checking' ? 'Reading the stars' : '● Offline'}
152	          </span>
153	          <Button variant="ghost" size="icon" onClick={() => setSettings(true)} aria-label="Settings"><SettingsIcon /></Button>
154	        </div>
155	      </header>
156	
157	      <ResizablePanelGroup orientation="horizontal" className="min-h-0 flex-1">
158	        <ResizablePanel defaultSize="19" minSize="14">
159	          <MailNav items={items} filter={filter} onFilter={setFilter} source={source} onSource={setSource} onSync={runSync} onConnect={connectMicrosoft} onDemo={showDemo} missed={missed} onPromote={promote} />
160	        </ResizablePanel>
161	        <ResizableHandle />
162	        <ResizablePanel defaultSize="33" minSize="22" className="bg-card/40">
163	          <MailList items={visible} total={items.length} selectedId={selected?.id ?? null} query={query} onQuery={setQuery} onSelect={choose}
164	            hasMore={!demo && loadedCount < remoteTotal} loadingMore={loadingMore} onLoadMore={loadMore} />
165	        </ResizablePanel>
166	        <ResizableHandle />
167	        <ResizablePanel defaultSize="48" minSize="30">
168	          <section aria-label="Work item detail" className="flex h-full min-h-0 flex-col bg-card/60">
169	            {selected
170	              ? <MailDetail item={selected} demo={demo} onStatus={changeStatus} onToast={setToast} onHandoff={handoff} onDismiss={dismiss} />
171	              : locked
172	                ? <UnlockPanel onUnlock={unlock} />
173	                : <div className="m-auto max-w-sm p-8 text-center">
174	                    <h2 className="font-serif text-xl">Your tower is quiet.</h2>
175	                    <p className="mt-2 text-sm text-muted-foreground">Connect Microsoft Graph or explore the sample queue.</p>
176	                    <Button className="mt-4" onClick={showDemo}>Explore sample tasks</Button>
177	                  </div>}
178	          </section>
179	        </ResizablePanel>
180	      </ResizablePanelGroup>
181	
182	      {toast && (
183	        <div className="fixed top-4 left-1/2 z-[60] flex -translate-x-1/2 items-center gap-2 rounded-lg bg-primary px-3 py-2 text-sm font-semibold text-primary-foreground shadow-xl">
184	          {toast}
185	          <Button variant="ghost" size="icon" className="size-5 text-primary-foreground hover:bg-primary-foreground/10" onClick={() => setToast('')} aria-label="Dismiss notification"><XIcon /></Button>
186	        </div>
187	      )}
188	
189	      <CommandPalette open={palette} onOpenChange={setPalette} items={items} onSelect={choose} onSync={runSync} onConnect={connectMicrosoft} onDemo={showDemo} onSettings={() => setSettings(true)} />
190	      <SettingsDialog ready={state === 'ready'} open={settings} onOpenChange={setSettings} />
191	    </div>
192	  )
193	}
