1	export type WorkStatus = 'pending' | 'in_progress' | 'blocked' | 'done' | 'dismissed'
2	export type SourceKind = 'outlook_email' | 'teams_message' | 'manual'
3	
4	export interface WorkItem { id: string; title: string; summary: string | null; status: WorkStatus; source_kind: SourceKind; source_external_id: string | null; source_url: string | null; assigned_agent: string | null; due_at: string | null; created_at: string; updated_at: string; evidence?: Evidence[] }
5	export interface Evidence { id?: string; source_kind: SourceKind; external_id: string; excerpt: string | null; observed_at: string }
6	export interface Health { status: string; service: string }
7	// The envelope every paginated list endpoint returns (backend/app/schemas.py WorkItemPage) — never a bare array.
8	export interface WorkItemPage { items: WorkItem[]; total: number; limit: number; offset: number }
9	export interface Source { id: string; kind: SourceKind; external_id: string; subject: string | null; url: string | null; excerpt: string | null; observed_at: string }
10	export interface SourcePage { items: Source[]; total: number; limit: number; offset: number }
11	
12	export class ApiError extends Error { constructor(public status: number) { super(`Request failed (${status})`) } }
13	let csrfToken: string | null = null
14	
15	async function request<T>(path: string, init?: RequestInit): Promise<T> {
16	  const method = (init?.method ?? 'GET').toUpperCase()
17	  const headers: Record<string, string> = { ...(init?.body ? { 'Content-Type': 'application/json' } : {}), ...(init?.headers as Record<string, string> | undefined) }
18	  if (!['GET', 'HEAD', 'OPTIONS'].includes(method) && csrfToken) headers['X-CSRF-Token'] = csrfToken
19	  const response = await fetch(path, { ...init, headers, credentials: 'same-origin' })
20	  if (!response.ok) throw new ApiError(response.status)
21	  return response.status === 204 ? ({} as T) : response.json() as Promise<T>
22	}
23	
24	export async function startLocalSession(localToken: string): Promise<void> {
25	  const response = await fetch('/api/session', { method: 'POST', credentials: 'same-origin', headers: { Authorization: `Bearer ${localToken}` } })
26	  if (!response.ok) throw new ApiError(response.status)
27	  csrfToken = (await response.json() as { csrf_token: string }).csrf_token
28	}
29	
30	export async function restoreLocalSession(): Promise<void> {
31	  const response = await fetch('/api/session', { credentials: 'same-origin' })
32	  if (!response.ok) throw new ApiError(response.status)
33	  csrfToken = (await response.json() as { csrf_token: string }).csrf_token || null
34	}
35	
36	export const beginMicrosoftConnect = async () => {
37	  const response = await request<{ authorization_url: string }>('/api/auth/microsoft/start')
38	  window.location.assign(response.authorization_url)
39	}
40	export const syncNow = () => request<{ created?: number; updated?: number; detail?: string }>('/api/sync', { method: 'POST' })
41	export const createDispatch = (id: string, client: 'codex' | 'claude-code', instruction: string) => request(`/api/work-items/${id}/dispatch`, { method: 'POST', body: JSON.stringify({ client, instruction }) })
42	
43	export const getHealth = () => request<Health>('/api/health')
44	export const getWorkItems = (params: { limit?: number; offset?: number; status?: WorkStatus; source_kind?: SourceKind } = {}) => {
45	  const search = new URLSearchParams()
46	  if (params.limit != null) search.set('limit', String(params.limit))
47	  if (params.offset != null) search.set('offset', String(params.offset))
48	  if (params.status) search.set('status', params.status)
49	  if (params.source_kind) search.set('source_kind', params.source_kind)
50	  const query = search.toString()
51	  return request<WorkItemPage>(`/api/work-items${query ? `?${query}` : ''}`)
52	}
53	export const getWorkItem = (id: string) => request<WorkItem>(`/api/work-items/${id}`)
54	export const updateWorkItem = (id: string, update: Partial<Pick<WorkItem, 'status' | 'assigned_agent'>>) => request<WorkItem>(`/api/work-items/${id}`, { method: 'PATCH', body: JSON.stringify(update) })
55	export const dismissWorkItem = (id: string) => request<WorkItem>(`/api/work-items/${id}/dismiss`, { method: 'POST' })
56	export const getSources = (params: { limit?: number; offset?: number } = {}) => {
57	  const search = new URLSearchParams()
58	  if (params.limit != null) search.set('limit', String(params.limit))
59	  if (params.offset != null) search.set('offset', String(params.offset))
60	  const query = search.toString()
61	  return request<SourcePage>(`/api/sources${query ? `?${query}` : ''}`)
62	}
63	export const promoteSource = (sourceId: string) => request<WorkItem>(`/api/sources/${sourceId}/promote`, { method: 'POST' })
