import { afterEach, describe, expect, it, vi } from 'vitest'
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import App from './App'
import type { WorkItem } from './api'

afterEach(() => { cleanup(); vi.unstubAllGlobals() })

const item = (id: string, title: string, rest: Partial<WorkItem> = {}): WorkItem => ({
  id, title, summary: null, status: 'pending', source_kind: 'outlook_email',
  source_external_id: `outlook_email:${id}`, source_url: null, assigned_agent: null,
  due_at: null, created_at: '', updated_at: '', ...rest,
})

// Unlike the suite's pagedQueue, this mock HONOURS the offset by slicing, the way a real
// server does. pagedQueue returns its second page for any nonzero offset, which cannot
// distinguish a correct offset from an off-by-one.
const slicingQueue = (fetchMock: ReturnType<typeof vi.fn>) => {
  const all = [item('a', 'First item'), item('b', 'Second item'), item('c', 'Third item')]
  const seen: number[] = []
  fetchMock.mockImplementation(async (path: string) => {
    const url = new URL(path, 'http://localhost')
    if (url.pathname === '/api/work-items') {
      const offset = Number(url.searchParams.get('offset') ?? '0')
      const limit = Number(url.searchParams.get('limit') ?? '2')
      seen.push(offset)
      return { ok: true, status: 200, json: async () => ({ items: all.slice(offset, offset + limit), total: all.length, limit, offset }) }
    }
    if (url.pathname === '/api/sources') return { ok: true, status: 200, json: async () => ({ items: [], total: 0, limit: 200, offset: 0 }) }
    if (url.pathname === '/api/session') return { ok: true, status: 200, json: async () => ({ csrf_token: 'csrf-test' }) }
    if (url.pathname.endsWith('/dismiss')) return { ok: true, status: 200, json: async () => ({ ...all[0], status: 'dismissed' }) }
    return { ok: true, status: 200, json: async () => ({ status: 'ok', service: 'workboard' }) }
  })
  return { seen }
}

describe('scratch: dismiss then load more against an offset-honouring server', () => {
  it('does not refetch an already-loaded row after a dismissal', async () => {
    const fetchMock = vi.fn(); vi.stubGlobal('fetch', fetchMock)
    const { seen } = slicingQueue(fetchMock)
    render(<App />)
    await screen.findByText('First item')
    await screen.findByText('Second item')

    // Dismiss the first row. The server total stays 3; two rows have still been fetched.
    fireEvent.click(screen.getByText('First item'))
    const dismissBtn = await screen.findByRole('button', { name: /dismiss/i })
    fireEvent.click(dismissBtn)
    await waitFor(() => expect(screen.queryByText('First item')).toBeNull())

    const loadMore = screen.getByRole('button', { name: /load more/i })
    fireEvent.click(loadMore)
    await screen.findByText('Third item')

    console.log('OFFSETS REQUESTED:', JSON.stringify(seen))
    console.log('Second item rendered count:', screen.queryAllByText('Second item').length)
    expect(seen[seen.length - 1]).toBe(2)
    expect(screen.queryAllByText('Second item')).toHaveLength(1)
  })
})
