import { afterEach, describe, expect, it, vi } from 'vitest'
import { cleanup, fireEvent, render, screen, within } from '@testing-library/react'
import App from './App'
import type { Source, WorkItem } from './api'
import { demoItems } from '@/lib/work-items'

afterEach(() => {
  cleanup()
  vi.unstubAllGlobals()
})

const item = (id: string, title: string, rest: Partial<WorkItem> = {}): WorkItem => ({
  id, title, summary: null, status: 'pending', source_kind: 'outlook_email', source_external_id: `outlook_email:${id}`,
  source_url: null, assigned_agent: null, due_at: null, created_at: '', updated_at: '', ...rest,
})

const offsetOf = (path: string) => new URL(path, 'http://localhost').searchParams.get('offset') ?? '0'

// One source the queue never promoted, so the MISSED panel has something to offer, and one
// that item 'a' already came from, which the panel must leave out.
const missedSource: Source = {
  id: 's1', kind: 'outlook_email', external_id: 'outlook_email:z', subject: 'Missed source',
  url: null, excerpt: null, observed_at: '',
}
const promotedSource: Source = {
  id: 's0', kind: 'outlook_email', external_id: 'outlook_email:a', subject: 'Already in the queue',
  url: null, excerpt: null, observed_at: '',
}
const promotedItem = item('p', 'Promoted item', { source_external_id: missedSource.external_id })

// The page a server hands back for `offset`, sliced out of `all` the way a real LIMIT/OFFSET
// query does. The page size is the server's to choose, not the caller's: the app asks for
// PAGE_LIMIT (50) and still gets two, so an off-by-one offset resurfaces a row that is already
// on screen instead of quietly landing on the same "second page" a fixed second page would serve.
const pageAt = (all: WorkItem[], path: string, size = 2) => {
  const offset = Number(offsetOf(path))
  return { ok: true, status: 200, json: async () => ({ items: all.slice(offset, offset + size), total: all.length, limit: size, offset }) }
}

// Serves three work items over pages of two, so a page boundary is reachable, and answers
// every other endpoint the app touches during boot (health, session, sources, dismiss, promote).
// `dismissFails` makes the dismiss endpoint refuse, so the optimistic removal has to roll back.
const pagedQueue = (fetchMock: ReturnType<typeof vi.fn>, { dismissFails = false } = {}) => {
  const all = [item('a', 'First item'), item('b', 'Second item'), item('c', 'Third item')]
  const [firstPage, secondPage] = [all.slice(0, 2), all.slice(2)]
  fetchMock.mockImplementation(async (path: string) => {
    const url = new URL(path, 'http://localhost')
    if (url.pathname === '/api/work-items') return pageAt(all, path)
    if (url.pathname === '/api/sources') {
      return { ok: true, status: 200, json: async () => ({ items: [promotedSource, missedSource], total: 2, limit: 200, offset: 0 }) }
    }
    if (url.pathname.endsWith('/promote')) return { ok: true, status: 200, json: async () => promotedItem }
    if (url.pathname === '/api/session') return { ok: true, status: 200, json: async () => ({ csrf_token: 'csrf-test' }) }
    if (url.pathname.endsWith('/dismiss')) {
      if (dismissFails) return { ok: false, status: 500, json: async () => ({ detail: 'nope' }) }
      const dismissedId = url.pathname.split('/')[3]
      const dismissed = all.find(i => i.id === dismissedId)
      return { ok: true, status: 200, json: async () => ({ ...dismissed, status: 'dismissed' }) }
    }
    return { ok: true, status: 200, json: async () => ({ status: 'ok', service: 'workboard' }) }
  })
  return { firstPage, secondPage }
}

// Six items over pages of two, where the server hands back rows that were dismissed in an
// earlier session. They arrive inside the page and consume offset, but never join the visible
// queue — so the count of rows already fetched cannot be read off `items.length` alone.
const queueWithDismissedRows = (fetchMock: ReturnType<typeof vi.fn>) => {
  const all = [
    item('a', 'First item', { status: 'dismissed' }), item('b', 'Second item'),
    item('c', 'Third item', { status: 'dismissed' }), item('d', 'Fourth item'),
    item('e', 'Fifth item'), item('f', 'Sixth item'),
  ]
  fetchMock.mockImplementation(async (path: string) => {
    const url = new URL(path, 'http://localhost')
    if (url.pathname === '/api/work-items') return pageAt(all, path)
    if (url.pathname === '/api/sources') return { ok: true, status: 200, json: async () => ({ items: [], total: 0, limit: 200, offset: 0 }) }
    if (url.pathname === '/api/session') return { ok: true, status: 200, json: async () => ({ csrf_token: 'csrf-test' }) }
    return { ok: true, status: 200, json: async () => ({ status: 'ok', service: 'workboard' }) }
  })
}

// Two items, both delivered on the first page (limit covers the whole total), so "Load more"
// is already absent before anything is promoted — the baseline the resurrection bug breaks.
const fullQueue = (fetchMock: ReturnType<typeof vi.fn>) => {
  const loaded = [item('a', 'First item'), item('b', 'Second item')]
  fetchMock.mockImplementation(async (path: string) => {
    const url = new URL(path, 'http://localhost')
    if (url.pathname === '/api/work-items') {
      return { ok: true, status: 200, json: async () => ({ items: loaded, total: loaded.length, limit: 50, offset: Number(offsetOf(path)) }) }
    }
    if (url.pathname === '/api/sources') {
      return { ok: true, status: 200, json: async () => ({ items: [missedSource], total: 1, limit: 200, offset: 0 }) }
    }
    if (url.pathname.endsWith('/promote')) return { ok: true, status: 200, json: async () => promotedItem }
    if (url.pathname === '/api/session') return { ok: true, status: 200, json: async () => ({ csrf_token: 'csrf-test' }) }
    return { ok: true, status: 200, json: async () => ({ status: 'ok', service: 'workboard' }) }
  })
  return { loaded }
}

// Five items over pages of two, so a third page sits behind the second and each Load more
// has to trust the envelope's `total` rather than the size of the page it just received.
const deepQueue = (fetchMock: ReturnType<typeof vi.fn>) => {
  const pages = [
    [item('a', 'First item'), item('b', 'Second item')],
    [item('c', 'Third item'), item('d', 'Fourth item')],
    [item('e', 'Fifth item')],
  ]
  fetchMock.mockImplementation(async (path: string) => {
    const url = new URL(path, 'http://localhost')
    if (url.pathname === '/api/work-items') {
      const page = pages[Number(offsetOf(path)) / 2] ?? []
      return { ok: true, status: 200, json: async () => ({ items: page, total: 5, limit: 2, offset: Number(offsetOf(path)) }) }
    }
    if (url.pathname === '/api/sources') return { ok: true, status: 200, json: async () => ({ items: [], total: 0, limit: 200, offset: 0 }) }
    if (url.pathname === '/api/session') return { ok: true, status: 200, json: async () => ({ csrf_token: 'csrf-test' }) }
    return { ok: true, status: 200, json: async () => ({ status: 'ok', service: 'workboard' }) }
  })
}

describe('Pagination', () => {
  it('pagination requests the next offset when Load more is clicked', async () => {
    const fetchMock = vi.fn()
    pagedQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText('First item')
    fireEvent.click(await within(queue).findByRole('button', { name: 'Load more' }))
    await within(queue).findByText('Third item')

    const workItemCalls = fetchMock.mock.calls.filter(([path]) => new URL(String(path), 'http://localhost').pathname === '/api/work-items')
    expect(workItemCalls.map(([path]) => offsetOf(String(path)))).toContain('2')
  })

  it('pagination stops offering Load more once every item has loaded', async () => {
    const fetchMock = vi.fn()
    pagedQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText('First item')
    fireEvent.click(await within(queue).findByRole('button', { name: 'Load more' }))
    await within(queue).findByText('Third item')

    expect(within(queue).queryByRole('button', { name: 'Load more' })).toBeNull()
  })

  it('pagination keeps paging past the second page while the envelope total exceeds what is loaded', async () => {
    const fetchMock = vi.fn()
    deepQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText('First item')
    fireEvent.click(await within(queue).findByRole('button', { name: 'Load more' }))
    await within(queue).findByText('Third item')
    fireEvent.click(await within(queue).findByRole('button', { name: 'Load more' }))
    await within(queue).findByText('Fifth item')
  })

  it('pagination is not offered once the sample queue replaces the real one', async () => {
    const fetchMock = vi.fn()
    pagedQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByRole('button', { name: 'Load more' })
    fireEvent.click(screen.getByRole('button', { name: 'View sample' }))
    await within(queue).findByText(demoItems[0].title)

    expect(within(queue).queryByRole('button', { name: 'Load more' })).toBeNull()
  })
})

// The two manual triage corrections live in one block so that both stay inside the
// `pagination|dismiss` gate, which vitest matches against the full describe + it name.
describe('Promote and dismiss', () => {
  it('dismiss removes the item from the visible list', async () => {
    const fetchMock = vi.fn()
    const { firstPage } = pagedQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText(firstPage[0].title)
    fireEvent.click(await screen.findByRole('button', { name: 'Dismiss' }))

    await within(queue).findByText(firstPage[1].title)
    expect(within(queue).queryByText(firstPage[0].title)).toBeNull()
  })

  it('dismiss sends the CSRF token header on its write request', async () => {
    const fetchMock = vi.fn()
    const { firstPage } = pagedQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText(firstPage[0].title)
    fireEvent.click(await screen.findByRole('button', { name: 'Dismiss' }))
    await within(queue).findByText(firstPage[1].title)

    const dismissCall = fetchMock.mock.calls.find(([path]) => String(path).includes('/dismiss'))
    expect(dismissCall).toBeTruthy()
    const headers = dismissCall?.[1]?.headers as Record<string, string>
    expect(headers['X-CSRF-Token']).toBe('csrf-test')
  })

  // Dismissing is a status transition, not a delete, so the server's unfiltered total is
  // unchanged and the page still waiting behind it must stay reachable.
  it('dismiss leaves the unloaded page reachable behind Load more', async () => {
    const fetchMock = vi.fn()
    const { firstPage } = pagedQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText(firstPage[0].title)
    fireEvent.click(await screen.findByRole('button', { name: 'Dismiss' }))
    await within(queue).findByText(firstPage[1].title)

    fireEvent.click(await within(queue).findByRole('button', { name: 'Load more' }))
    await within(queue).findByText('Third item')

    // The dismissed row still counts toward what has been fetched, so the next page starts
    // after it. Forgetting that asks for the offset one too low and refetches a visible row.
    expect(within(queue).getAllByText(firstPage[1].title)).toHaveLength(1)
  })

  // A dismissal the server refuses is rolled back, so the row rejoins the queue — and must go
  // back to counting once, not twice, or the page behind it stops being reachable.
  it('dismiss that the server rejects leaves the unloaded page reachable behind Load more', async () => {
    const fetchMock = vi.fn()
    const { firstPage } = pagedQueue(fetchMock, { dismissFails: true })
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText(firstPage[0].title)
    fireEvent.click(await screen.findByRole('button', { name: 'Dismiss' }))
    await screen.findByText('Could not dismiss that item.')
    await within(queue).findByText(firstPage[0].title)

    fireEvent.click(await within(queue).findByRole('button', { name: 'Load more' }))
    await within(queue).findByText('Third item')
    expect(within(queue).getAllByText(firstPage[1].title)).toHaveLength(1)
  })

  // Rows the server reports as already dismissed never reach the queue, so each Load more has
  // to offset past them as well as past the rows on screen.
  it('dismissed rows delivered inside a page still count toward the next Load more offset', async () => {
    const fetchMock = vi.fn()
    queueWithDismissedRows(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText('Second item')
    fireEvent.click(await within(queue).findByRole('button', { name: 'Load more' }))
    await within(queue).findByText('Fourth item')
    fireEvent.click(await within(queue).findByRole('button', { name: 'Load more' }))
    await within(queue).findByText('Sixth item')

    expect(within(queue).getAllByText('Second item')).toHaveLength(1)
    expect(within(queue).getAllByText('Fourth item')).toHaveLength(1)
    expect(within(queue).queryByText('First item')).toBeNull()
    expect(within(queue).queryByRole('button', { name: 'Load more' })).toBeNull()
  })

  it('promote posts the missed source to its promote endpoint and shows the new item in the queue', async () => {
    const fetchMock = vi.fn()
    pagedQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const panel = await screen.findByRole('group', { name: 'Missed sources' })
    fireEvent.click(within(panel).getByRole('button', { name: 'Promote' }))

    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText(promotedItem.title)

    const promoteCall = fetchMock.mock.calls.find(([path]) => String(path).endsWith('/promote'))
    expect(promoteCall?.[0]).toBe(`/api/sources/${missedSource.id}/promote`)
    expect(promoteCall?.[1]?.method).toBe('POST')
    expect((promoteCall?.[1]?.headers as Record<string, string>)['X-CSRF-Token']).toBe('csrf-test')
  })

  it('promote only offers sources that are not already in the queue', async () => {
    const fetchMock = vi.fn()
    pagedQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const panel = await screen.findByRole('group', { name: 'Missed sources' })
    await within(panel).findByText(missedSource.subject as string)
    expect(within(panel).queryByText(promotedSource.subject as string)).toBeNull()
  })

  // The mirrored resurrection bug: promote() bumped remoteTotal without ever bumping the count
  // of rows already fetched, so a fully loaded queue thought a page was still missing, offered
  // "Load more", and refetching landed a row that was already on screen under a different id.
  it('promote on a fully loaded queue does not resurrect Load more or duplicate a row', async () => {
    const fetchMock = vi.fn()
    const { loaded } = fullQueue(fetchMock)
    vi.stubGlobal('fetch', fetchMock)

    render(<App />)

    const panel = await screen.findByRole('group', { name: 'Missed sources' })
    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText(loaded[0].title)
    expect(within(queue).queryByRole('button', { name: 'Load more' })).toBeNull()

    fireEvent.click(within(panel).getByRole('button', { name: 'Promote' }))
    await within(queue).findByText(promotedItem.title)

    expect(within(queue).queryByRole('button', { name: 'Load more' })).toBeNull()
    expect(within(queue).getAllByText(loaded[1].title)).toHaveLength(1)
  })
})

import { useEffect, useMemo, useState } from 'react'
import { SearchIcon, SettingsIcon, XIcon } from 'lucide-react'
import { ApiError, beginMicrosoftConnect, createDispatch, dismissWorkItem, getHealth, getSources, getWorkItem, getWorkItems, promoteSource, restoreLocalSession, startLocalSession, syncNow, updateWorkItem, type Source, type SourceKind, type WorkItem, type WorkStatus } from './api'
import { CommandPalette } from '@/components/command-palette'
import { MailDetail } from '@/components/mail-detail'
import { MailList } from '@/components/mail-list'
import { MailNav } from '@/components/mail-nav'
import { SettingsDialog } from '@/components/settings-dialog'
import { UnlockPanel } from '@/components/unlock-panel'
import { Button } from '@/components/ui/button'
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from '@/components/ui/resizable'
import { demoItems } from '@/lib/work-items'

const PAGE_LIMIT = 50

export default function App() {
  const [items, setItems] = useState<WorkItem[]>([])
  const [selected, setSelected] = useState<WorkItem | null>(null)
  const [filter, setFilter] = useState<WorkStatus | 'all'>('all')
  const [source, setSource] = useState<SourceKind | 'all'>('all')
  const [query, setQuery] = useState('')
  const [state, setState] = useState<'checking' | 'ready' | 'offline'>('checking')
  const [demo, setDemo] = useState(false)
  const [settings, setSettings] = useState(false)
  const [palette, setPalette] = useState(false)
  const [toast, setToast] = useState('')
  const [locked, setLocked] = useState(false)
  const [remoteTotal, setRemoteTotal] = useState(0)
  // Rows the server has handed us but that never entered `items` because they were already
  // dismissed on arrival. `items.length` alone under-counts what's been fetched once a row
  // leaves the array, so this correction travels with it instead of a separately tracked
  // "loaded" counter — the fetched count can only move in the same call that moves `items`,
  // so promoting (which only ever grows `items`) cannot leave it behind the way it left
  // `loadedCount` behind before.
  const [dismissedCount, setDismissedCount] = useState(0)
  const [loadingMore, setLoadingMore] = useState(false)
  const [missed, setMissed] = useState<Source[]>([])
  const fetchedCount = items.length + dismissedCount

  const loadMissed = async (loadedItems: WorkItem[]) => {
    try {
      const page = await getSources({ limit: 200 })
      const promoted = new Set(loadedItems.map(i => i.source_external_id).filter((id): id is string => Boolean(id)))
      setMissed((page.items ?? []).filter(candidate => !promoted.has(candidate.external_id)))
    } catch { setMissed([]) }
  }

  const loadWork = async () => {
    try {
      await getHealth()
      await restoreLocalSession()
      const page = await getWorkItems()
      const work = page.items.filter(i => i.status !== 'dismissed')
      setState('ready'); setLocked(false); setDemo(false)
      setItems(work); setSelected(work[0] ?? null)
      setRemoteTotal(page.total); setDismissedCount(page.items.length - work.length)
      void loadMissed(work)
    } catch (error) {
      if (error instanceof ApiError && (error.status === 401 || error.status === 503)) { setState('offline'); setLocked(true); return }
      setState('offline'); setDemo(true); setItems(demoItems); setSelected(demoItems[0])
      setRemoteTotal(demoItems.length); setDismissedCount(0); setMissed([])
    }
  }

  const loadMore = async () => {
    setLoadingMore(true)
    try {
      const page = await getWorkItems({ limit: PAGE_LIMIT, offset: fetchedCount })
      const additions = page.items.filter(i => i.status !== 'dismissed')
      setItems(all => [...all, ...additions]); setRemoteTotal(page.total)
      setDismissedCount(count => count + (page.items.length - additions.length))
    } catch { setToast('Could not load more items.') }
    finally { setLoadingMore(false) }
  }

  useEffect(() => { void loadWork() }, [])

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key.toLowerCase() === 'k' && (event.metaKey || event.ctrlKey)) { event.preventDefault(); setPalette(open => !open) }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  const unlock = async (token: string) => {
    try { await startLocalSession(token); await loadWork() } catch { setToast('That local token could not unlock Magic Tower.') }
  }
  const connectMicrosoft = async () => {
    try { await beginMicrosoftConnect() } catch { setToast('Microsoft connection could not start.') }
  }
  const runSync = async () => {
    try { const result = await syncNow(); await loadWork(); setToast(result.detail || 'Microsoft messages synced.') } catch { setToast('Sync could not be completed.') }
  }
  const handoff = async (item: WorkItem, client: 'codex' | 'claude-code') => {
    try { await createDispatch(item.id, client, 'Review the local Magic Tower item and propose the next safe action.'); setToast(`Queued a ${client} handoff.`) } catch { setToast('Could not queue the agent handoff.') }
  }
  const showDemo = () => {
    setDemo(true); setItems(demoItems); setSelected(demoItems[0]); setToast('Showing sample items — connect the API for your work queue.')
  }
  const choose = async (item: WorkItem) => {
    setSelected(item)
    if (!demo) try { setSelected(await getWorkItem(item.id)) } catch { /* list summary remains usable */ }
  }
  const changeStatus = async (status: WorkStatus) => {
    if (!selected) return
    const old = selected
    const next = { ...old, status }
    setSelected(next); setItems(all => all.map(i => i.id === next.id ? next : i))
    if (!demo) try {
      const saved = await updateWorkItem(old.id, { status })
      setSelected(saved); setItems(all => all.map(i => i.id === saved.id ? saved : i))
    } catch {
      setSelected(old); setItems(all => all.map(i => i.id === old.id ? old : i)); setToast('Could not save that change.')
    }
  }
  const dismiss = async (item: WorkItem) => {
    // Dismissing moves a row to the 'dismissed' status rather than deleting it, so the server's
    // unfiltered total is unchanged — decrementing it here would strand the still-unfetched pages.
    // The row still counts toward what's been fetched, so that moves from `items` into
    // `dismissedCount` rather than disappearing from the fetched count entirely.
    setItems(all => all.filter(i => i.id !== item.id))
    setDismissedCount(count => count + 1)
    setSelected(current => current?.id === item.id ? null : current)
    if (demo) { setToast('Dismissed the sample item.'); return }
    try { await dismissWorkItem(item.id); setToast('Dismissed. It will stay out of the queue.') }
    catch {
      setItems(all => [item, ...all]); setDismissedCount(count => count - 1); setSelected(item)
      setToast('Could not dismiss that item.')
    }
  }
  const promote = async (candidate: Source) => {
    try {
      const created = await promoteSource(candidate.id)
      setMissed(all => all.filter(s => s.id !== candidate.id))
      setItems(all => [created, ...all]); setSelected(created); setRemoteTotal(t => t + 1)
      setToast('Promoted to your work queue.')
    } catch { setToast('Could not promote that source.') }
  }

  const visible = useMemo(
    () => items.filter(i => (filter === 'all' || i.status === filter) && (source === 'all' || i.source_kind === source) && `${i.title} ${i.summary ?? ''}`.toLowerCase().includes(query.toLowerCase())),
    [items, filter, source, query],
  )

  return (
    <div className="flex h-screen flex-col">
      <header className="flex items-center justify-between gap-3 border-b border-border px-4 py-2.5">
        <div className="flex items-center gap-3">
          <img src="/magic-tower-logo.png" alt="Magic Tower" className="size-8 object-contain" />
          <div>
            <h1 className="font-serif text-base leading-tight">Magic Tower</h1>
            <p className="text-[0.68rem] text-muted-foreground">A private task grimoire</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => setPalette(true)}>
            <SearchIcon />Search
            <kbd className="ml-2 rounded-sm bg-secondary px-1.5 py-0.5 text-[0.65rem] text-muted-foreground">⌘K</kbd>
          </Button>
          <span className={state === 'ready' ? 'text-xs text-emerald-300' : 'text-xs text-muted-foreground'}>
            {state === 'ready' ? '● Synced locally' : state === 'checking' ? 'Reading the stars' : '● Offline'}
          </span>
          <Button variant="ghost" size="icon" onClick={() => setSettings(true)} aria-label="Settings"><SettingsIcon /></Button>
        </div>
      </header>

      <ResizablePanelGroup orientation="horizontal" className="min-h-0 flex-1">
        <ResizablePanel defaultSize="19" minSize="14">
          <MailNav items={items} filter={filter} onFilter={setFilter} source={source} onSource={setSource} onSync={runSync} onConnect={connectMicrosoft} onDemo={showDemo} missed={missed} onPromote={promote} />
        </ResizablePanel>
        <ResizableHandle />
        <ResizablePanel defaultSize="33" minSize="22" className="bg-card/40">
          <MailList items={visible} total={items.length} selectedId={selected?.id ?? null} query={query} onQuery={setQuery} onSelect={choose}
            hasMore={!demo && fetchedCount < remoteTotal} loadingMore={loadingMore} onLoadMore={loadMore} />
        </ResizablePanel>
        <ResizableHandle />
        <ResizablePanel defaultSize="48" minSize="30">
          <section aria-label="Work item detail" className="flex h-full min-h-0 flex-col bg-card/60">
            {selected
              ? <MailDetail item={selected} demo={demo} onStatus={changeStatus} onToast={setToast} onHandoff={handoff} onDismiss={dismiss} />
              : locked
                ? <UnlockPanel onUnlock={unlock} />
                : <div className="m-auto max-w-sm p-8 text-center">
                    <h2 className="font-serif text-xl">Your tower is quiet.</h2>
                    <p className="mt-2 text-sm text-muted-foreground">Connect Microsoft Graph or explore the sample queue.</p>
                    <Button className="mt-4" onClick={showDemo}>Explore sample tasks</Button>
                  </div>}
          </section>
        </ResizablePanel>
      </ResizablePanelGroup>

      {toast && (
        <div className="fixed top-4 left-1/2 z-[60] flex -translate-x-1/2 items-center gap-2 rounded-lg bg-primary px-3 py-2 text-sm font-semibold text-primary-foreground shadow-xl">
          {toast}
          <Button variant="ghost" size="icon" className="size-5 text-primary-foreground hover:bg-primary-foreground/10" onClick={() => setToast('')} aria-label="Dismiss notification"><XIcon /></Button>
        </div>
      )}

      <CommandPalette open={palette} onOpenChange={setPalette} items={items} onSelect={choose} onSync={runSync} onConnect={connectMicrosoft} onDemo={showDemo} onSettings={() => setSettings(true)} />
      <SettingsDialog ready={state === 'ready'} open={settings} onOpenChange={setSettings} />
    </div>
  )
}
